  q.push(createMCQ("Which 102-story Art Deco skyscraper in Midtown Manhattan held the title of world's tallest building from 1931 until 1970?", "Empire State Building", "Chrysler Building", "Rockefeller Center", "Built in an astonishing 13.5 months during the Great Depression, the Empire State Building rose to 381 meters at its roof (443.2m to tip).", mcqIdx++));
